@dataclass
class CachedIssue:
    """
    キャッシュされたIssue情報
    
    差分スキャン機能で使用。変更されていない行のIssueを
    再検出せずにキャッシュから取得するためのデータ構造。
    
    Attributes:
        file: ファイルパス
        line: 行番号（Noneの場合はファイル全体に関するIssue）
        line_end: 終了行（範囲指定時、Noneの場合は単一行）
        issue_type: Issue種別（1-25）
        description: Issue説明
        fix: 修正提案
        content_hash: 該当行のハッシュ（変更検知用）
    """
    file: str
    line: Optional[int]
    line_end: Optional[int]
    issue_type: int
    description: str
    fix: str
    content_hash: str


@dataclass
class ModifiedRange:
    """
    変更された行範囲
    
    unified diffから抽出された変更範囲。
    差分スキャンで再検出対象を特定するために使用。
    
    Attributes:
        file: ファイルパス
        start_line: 変更開始行（1-indexed）
        end_line: 変更終了行（1-indexed、inclusive）
        diff_content: 該当部分の差分内容
    """
    file: str
    start_line: int
    end_line: int
    diff_content: str


@dataclass
class SICError:
    """
    SIC検証エラーの構造化情報
    
    3者比較プロンプトで使用。エラーの種類と詳細を
    LLMに明確に伝えるための構造化データ。
    
    Attributes:
        error_type: エラータイプ
            - "TOP_LEVEL_POLLUTION": 属性がクラス外に漏出
            - "SYMBOL_DELETION": クラス/関数の削除
            - "ATTRIBUTE_DRIFT": 重要属性の消失
            - "CLASS_DELETION": クラスの消失
            - "TYPE_ANNOTATION_DRIFT": 型ヒントの消失
            - "SYNTAX_ERROR": 構文エラー
        affected_class: 影響を受けたクラス名
        affected_items: 影響を受けた属性/シンボル/関数のリスト
        human_readable: 人間可読なエラーメッセージ（従来形式）
    """
    error_type: str
    affected_class: Optional[str]
    affected_items: List[str]
    human_readable: str


# ============================================
# Complexity Assessment
# ============================================

class ComplexityAssessor:
    """複雑度判定クラス(3層防御)"""
    
    def __init__(self):
        self.simple_keywords = self._init_simple_keywords()
        self.medium_keywords = self._init_medium_keywords()
        self.complex_keywords = self._init_complex_keywords()
        self.exclusion_patterns = self._init_exclusion_patterns()
        
        # ✅ 既存ファイルを読み込む
        self.existing_files = {}
        
        # サポートされるファイル拡張子の定義
        # repository_analyzer.pyのSUPPORTED_LANGUAGESに対応 + 追加の一般的な言語
        supported_extensions = {
            # Python
            '.py', '.pyi',
            # JavaScript/TypeScript
            '.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs',
            # HTML/CSS
            '.html', '.htm', '.css', '.scss', '.sass', '.less',
            # 設定・データファイル
            '.json', '.yml', '.yaml', '.toml', '.ini', '.cfg', '.xml',
            # ドキュメント
            '.md', '.mdx', '.txt', '.rst',
            # その他の言語
            '.rb',      # Ruby
            '.php',     # PHP
            '.java',    # Java
            '.c', '.cpp', '.cc', '.cxx', '.h', '.hpp',  # C/C++
            '.cs',      # C#
            '.go',      # Go
            '.rs',      # Rust
            '.swift',   # Swift
            '.kt',      # Kotlin
            '.scala',   # Scala
            '.sh', '.bash',  # Shell
            '.ps1',     # PowerShell
            '.sql',     # SQL
            '.vue',     # Vue
            '.svelte',  # Svelte
        }
        
        try:
            scanned_count = 0
            loaded_count = 0
            
            # カレントディレクトリ内のすべてのファイルをスキャン
            for file_path in Path.cwd().glob("*.*"):
                scanned_count += 1
                
                # サポートされる拡張子のみ読み込む
                if file_path.suffix.lower() in supported_extensions:
                    try:
                        content = file_path.read_text(encoding='utf-8')
                        self.existing_files[file_path.name] = content
                        loaded_count += 1
                        logger.debug(f"[ComplexityAssessor] Loaded: {file_path.name} ({len(content)} chars)")
                    except Exception as read_error:
                        logger.debug(f"[ComplexityAssessor] Failed to read {file_path.name}: {read_error}")
                        pass
            
            logger.debug(f"[ComplexityAssessor] Scanned {scanned_count} files, loaded {loaded_count} files")
            logger.debug(f"[ComplexityAssessor] Loaded files: {list(self.existing_files.keys())}")
            
        except Exception as e:
            logger.debug(f"⚠ Warning: Failed to scan some files: {e}")
            logger.debug(f"[ComplexityAssessor] Scan error: {e}")
        

        
